window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-03e895ad095c3df0"]={"versions": [{"id": "FIG-03e895ad095c3df0", "releases": ["R4.1.3", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Zuordnungsdiagramm im Kontext des AUTOSAR Classic Platform CAN-Treibers (<code>Can</code>). Das Diagramm illustriert das architektonische Mapping zwischen logischen Hardware Receive Handles (<code>HRH</code>) des oberen Software-Layers (z. B. CAN Interface / <code>CanIf</code>) und den physischen CAN-Hardware-Nachrichtenobjekten (<code>Message Objects of CAN Hardware</code>) des CAN-Controllers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>HRH</code> (Hardware Receive Handle): Logische Bezeichner für Empfangsobjekte (<code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code>, <code>HRH = 3</code>).\n</li><li><code>Message Objects of CAN Hardware</code>: Acht physische Hardware-Mailboxen/Puffer des CAN-Controllers, jeweils unterteilt in die Felder <code>ID</code> (CAN Identifier), <code>DLC</code> (Data Length Code) und <code>SDU</code> (Service Data Unit / Nutzdaten).\n</li><li>Zuordnungen / Schnittstellen:\n<ul class=\"fig-list\"><li><code>HRH = 0</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li><li><code>HRH = 1</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 2</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 3</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li></ul>\n</li><li>Übergeordnete Klammer: Fasst alle 8 Nachrichtenobjekte als Gesamtheit der <code>Message Objects of CAN Hardware</code> zusammen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Konfigurationsbeziehung dar:</p>\n<ol class=\"fig-list\"><li>Empfängt der CAN-Controller Botschaften für <code>HRH = 0</code> oder <code>HRH = 3</code>, stehen jeweils drei Hardware-Objekte zur Pufferung bereit, um Datenverlust bei hoher Buslast abzufangen.\n</li><li>Für <code>HRH = 1</code> und <code>HRH = 2</code> erfolgt die Pufferung dediziert in jeweils genau einem Hardware-Objekt.\n</li><li>Bei erfolgreichem Empfang und Filterung signalisiert der CAN-Treiber das Ereignis unter Angabe des zugehörigen <code>HRH</code> an die übergeordnete Schicht (<code>CanIf</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die normative Konfiguration von Hardware-Objekten im CAN-Treiber (<code>CanHardwareObject</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>HRH</code> kann gemäß AUTOSAR CAN Driver Spezifikation entweder einem einzelnen Hardware-Objekt oder mehreren Hardware-Objekten (z. B. konfiguriert als Hardware-FIFO über den Parameter <code>CanHwObjectCount</code>) zugewiesen sein.\n</li><li>Entwickler und Integratoren müssen beachten, dass bei Mehrfachzuweisung (<code>HRH</code> auf mehrere Hardware-Objekte) identische Filterkonfigurationen auf Hardware-Ebene greifen und die Treiberimplementierung die Reihenfolge bzw. Konsistenz der empfangenen SDUs sicherstellen muss.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a5c0f89685c2c8f8", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Zuordnungsdiagramm im Kontext des AUTOSAR Classic Platform CAN-Treibers (<code>Can</code>). Das Diagramm illustriert das architektonische Mapping zwischen logischen Hardware Receive Handles (<code>HRH</code>) des oberen Software-Layers (z. B. CAN Interface / <code>CanIf</code>) und den physischen CAN-Hardware-Nachrichtenobjekten (<code>Message Objects of CAN Hardware</code>) des CAN-Controllers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>HRH</code> (Hardware Receive Handle): Logische Bezeichner für Empfangsobjekte (<code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code>, <code>HRH = 3</code>).\n</li><li><code>Message Objects of CAN Hardware</code>: Acht physische Hardware-Mailboxen/Puffer des CAN-Controllers, jeweils unterteilt in die Felder <code>ID</code> (CAN Identifier), <code>DLC</code> (Data Length Code) und <code>SDU</code> (Service Data Unit / Nutzdaten).\n</li><li>Zuordnungen / Schnittstellen:\n<ul class=\"fig-list\"><li><code>HRH = 0</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li><li><code>HRH = 1</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 2</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 3</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li></ul>\n</li><li>Übergeordnete Klammer: Fasst alle 8 Nachrichtenobjekte als Gesamtheit der <code>Message Objects of CAN Hardware</code> zusammen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Konfigurationsbeziehung dar:</p>\n<ol class=\"fig-list\"><li>Empfängt der CAN-Controller Botschaften für <code>HRH = 0</code> oder <code>HRH = 3</code>, stehen jeweils drei Hardware-Objekte zur Pufferung bereit, um Datenverlust bei hoher Buslast abzufangen.\n</li><li>Für <code>HRH = 1</code> und <code>HRH = 2</code> erfolgt die Pufferung dediziert in jeweils genau einem Hardware-Objekt.\n</li><li>Bei erfolgreichem Empfang und Filterung signalisiert der CAN-Treiber das Ereignis unter Angabe des zugehörigen <code>HRH</code> an die übergeordnete Schicht (<code>CanIf</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die normative Konfiguration von Hardware-Objekten im CAN-Treiber (<code>CanHardwareObject</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>HRH</code> kann gemäß AUTOSAR CAN Driver Spezifikation entweder einem einzelnen Hardware-Objekt oder mehreren Hardware-Objekten (z. B. konfiguriert als Hardware-FIFO über den Parameter <code>CanHwObjectCount</code>) zugewiesen sein.\n</li><li>Entwickler und Integratoren müssen beachten, dass bei Mehrfachzuweisung (<code>HRH</code> auf mehrere Hardware-Objekte) identische Filterkonfigurationen auf Hardware-Ebene greifen und die Treiberimplementierung die Reihenfolge bzw. Konsistenz der empfangenen SDUs sicherstellen muss.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e6188d242e96fc62", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Zuordnungsdiagramm im Kontext des AUTOSAR Classic Platform CAN-Treibers (<code>Can</code>). Das Diagramm illustriert das architektonische Mapping zwischen logischen Hardware Receive Handles (<code>HRH</code>) des oberen Software-Layers (z. B. CAN Interface / <code>CanIf</code>) und den physischen CAN-Hardware-Nachrichtenobjekten (<code>Message Objects of CAN Hardware</code>) des CAN-Controllers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>HRH</code> (Hardware Receive Handle): Logische Bezeichner für Empfangsobjekte (<code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code>, <code>HRH = 3</code>).\n</li><li><code>Message Objects of CAN Hardware</code>: Acht physische Hardware-Mailboxen/Puffer des CAN-Controllers, jeweils unterteilt in die Felder <code>ID</code> (CAN Identifier), <code>DLC</code> (Data Length Code) und <code>SDU</code> (Service Data Unit / Nutzdaten).\n</li><li>Zuordnungen / Schnittstellen:\n<ul class=\"fig-list\"><li><code>HRH = 0</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li><li><code>HRH = 1</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 2</code> ist direkt einem einzelnen Hardware-Objekt zugeordnet (1:1-Beziehung, Dedicated Object).\n</li><li><code>HRH = 3</code> ist über eine geschweifte Klammer einem Pufferpool aus 3 Hardware-Objekten zugeordnet (Hardware-FIFO / Multiplexing).\n</li></ul>\n</li><li>Übergeordnete Klammer: Fasst alle 8 Nachrichtenobjekte als Gesamtheit der <code>Message Objects of CAN Hardware</code> zusammen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Konfigurationsbeziehung dar:</p>\n<ol class=\"fig-list\"><li>Empfängt der CAN-Controller Botschaften für <code>HRH = 0</code> oder <code>HRH = 3</code>, stehen jeweils drei Hardware-Objekte zur Pufferung bereit, um Datenverlust bei hoher Buslast abzufangen.\n</li><li>Für <code>HRH = 1</code> und <code>HRH = 2</code> erfolgt die Pufferung dediziert in jeweils genau einem Hardware-Objekt.\n</li><li>Bei erfolgreichem Empfang und Filterung signalisiert der CAN-Treiber das Ereignis unter Angabe des zugehörigen <code>HRH</code> an die übergeordnete Schicht (<code>CanIf</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die normative Konfiguration von Hardware-Objekten im CAN-Treiber (<code>CanHardwareObject</code>):</p>\n<ul class=\"fig-list\"><li>Ein <code>HRH</code> kann gemäß AUTOSAR CAN Driver Spezifikation entweder einem einzelnen Hardware-Objekt oder mehreren Hardware-Objekten (z. B. konfiguriert als Hardware-FIFO über den Parameter <code>CanHwObjectCount</code>) zugewiesen sein.\n</li><li>Entwickler und Integratoren müssen beachten, dass bei Mehrfachzuweisung (<code>HRH</code> auf mehrere Hardware-Objekte) identische Filterkonfigurationen auf Hardware-Ebene greifen und die Treiberimplementierung die Reihenfolge bzw. Konsistenz der empfangenen SDUs sicherstellen muss.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-03e895ad095c3df0", "to": "FIG-a5c0f89685c2c8f8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildbeschnitt: Die am oberen Rand abgeschnittene Textzeile („... of Hardware Objects is configured via &quot;CanHwObjectCount&quot; [...]“) wurde entfernt.\n</li></ul>"}, {"from": "FIG-a5c0f89685c2c8f8", "to": "FIG-03e895ad095c3df0", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildbeschnitt: Die am oberen Rand abgeschnittene Textzeile („... of Hardware Objects is configured via &quot;CanHwObjectCount&quot; [...]“) ist wieder sichtbar.\n</li></ul>"}, {"from": "FIG-a5c0f89685c2c8f8", "to": "FIG-e6188d242e96fc62", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildbeschnitt: Am oberen Rand ist wieder ein Fragment der abgeschnittenen Textzeile („... of Hardware Objects is configured via &quot;CanHwObjectCount&quot; [...]“) sichtbar.\n</li></ul>"}]};
